cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && git fetch origin main 2>&1 | tail -1 && python3 - <<'PY'
import subprocess, re
out=subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True)
files=[f for f in out.split() if re.match(r'S\d+/E\d+\.md',f)]
transcribed=set()
for f in files:
    txt=subprocess.check_output(['git','show','origin/main:'+f],text=True)
    for m in re.finditer(r'Source: friend/[\w-]+ @ ([0-9a-f]{40})',txt):
        transcribed.add(m.group(1))
branch_of={}
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    for sha in subprocess.check_output(['git','rev-list','origin/friend/'+b],text=True).split():
        branch_of[sha]=b
missing=0
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    for sha in subprocess.check_output(['git','rev-list','origin/friend/'+b],text=True).split():
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' not in msg: continue
        subj=subprocess.check_output(['git','show','-s','--format=%s',sha],text=True).strip()
        if not subj.startswith('friend: '): continue
        if sha not in transcribed:
            missing+=1
print("missing utterances:",missing)
